import React, { useMemo } from 'react';
import { View, Text, TouchableOpacity, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../../context/ThemeContext';
import { WorkoutHistoryRecord } from '../../context/WorkoutHistoryContext';

interface Props {
    history: WorkoutHistoryRecord[];
    userName?: string;
}

// Export Header separately for flexible placement
export function DailyHeader({ dateString, greeting, streak, theme }: any) {
    return (
        <View className="mb-6">
            <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase font-bold tracking-widest mb-1">
                {dateString}
            </Text>
            <Text style={{ color: theme.colors.text }} className="text-xl font-bold mb-2">
                {greeting}
            </Text>
            {streak > 1 && (
                <View className="flex-row items-center">
                    <Ionicons name="flame" size={16} color="#FF9500" />
                    <Text style={{ color: '#FF9500' }} className="text-sm font-bold ml-1">
                        Você treinou {streak} dias seguidos!
                    </Text>
                </View>
            )}
        </View>
    );
}

export function DailySummary({ history, userName = "Braulio", showHeader = true }: Props & { showHeader?: boolean }) {
    const { theme } = useTheme();

    // 1. Calculate Date & Greeting
    const { dateString, greeting } = useMemo(() => {
        const now = new Date();
        const dateOptions: Intl.DateTimeFormatOptions = { weekday: 'long', day: 'numeric', month: 'short' };
        const formattedDate = now.toLocaleDateString('pt-BR', dateOptions);

        const hour = now.getHours();
        let greet = 'Bom dia';
        if (hour >= 12 && hour < 18) greet = 'Boa tarde';
        else if (hour >= 18) greet = 'Boa noite';

        return {
            dateString: formattedDate.charAt(0).toUpperCase() + formattedDate.slice(1),
            greeting: `${greet}, ${userName}! Bora manter o foco hoje 💪`
        };
    }, [userName]);

    // 2. Calculate Streak
    const streak = useMemo(() => {
        if (!history || history.length === 0) return 0;

        const sortedDates = [...new Set(history.map(h => new Date(h.date).toDateString()))]
            .map(d => new Date(d).getTime())
            .sort((a, b) => b - a);

        let currentStreak = 0;
        const today = new Date().setHours(0, 0, 0, 0);
        let checkDate = today;

        // Check if trained today
        if (sortedDates.includes(today)) {
            currentStreak++;
            checkDate -= 86400000; // Look for yesterday
        } else {
            // If not trained today, streak is valid if trained yesterday
            checkDate -= 86400000;
        }

        while (sortedDates.includes(checkDate)) {
            currentStreak++;
            checkDate -= 86400000;
        }

        return currentStreak;
    }, [history]);

    // 3. Get Today's Status & Last Workout
    const { status, type, duration, calories, exercises, lastWorkout, isCompleted } = useMemo(() => {
        const todayStr = new Date().toDateString();
        const todaysWorkout = history.find(h => new Date(h.date).toDateString() === todayStr);

        if (todaysWorkout) {
            const mins = Math.floor(todaysWorkout.duration / 60);
            const cals = Math.floor(mins * 5.5); // Estimate 5.5 cal/min

            return {
                status: 'Concluído',
                type: 'Musculação', // Could infer from exercises
                duration: `${mins} min`,
                calories: `${cals} kcal`,
                exercises: todaysWorkout.exercises,
                lastWorkout: todaysWorkout,
                isCompleted: true
            };
        }

        return {
            status: 'Não iniciado',
            type: 'Descanso / Treino',
            duration: '--',
            calories: '--',
            exercises: [],
            lastWorkout: null,
            isCompleted: false
        };
    }, [history]);


    // 4. Comparison Logic
    const getComparison = (exerciseId: string, currentSets: any[]) => {
        // Find previous workout with this exercise
        const previousWorkout = history
            .filter(h => h.id !== lastWorkout?.id) // Exclude current
            .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
            .find(h => h.exercises.some(e => e.id === exerciseId));

        if (!previousWorkout) return null;

        const prevEx = previousWorkout.exercises.find(e => e.id === exerciseId);
        if (!prevEx || !prevEx.sets || prevEx.sets.length === 0) return null;

        // Compare max weight
        const currentMax = Math.max(...currentSets.map(s => Number(s.kg || 0)));
        const prevMax = Math.max(...prevEx.sets.map(s => Number(s.kg || 0)));

        if (currentMax > prevMax) return { type: 'better', text: `+${currentMax - prevMax}kg` };
        if (currentMax < prevMax) return { type: 'worse', text: `${currentMax - prevMax}kg` };

        return { type: 'same', text: 'Manter' };
    };

    return (
        <View className="mb-10 px-6">
            {/* Header (Optional via prop) */}
            {showHeader && (
                <DailyHeader
                    dateString={dateString}
                    greeting={greeting}
                    streak={streak}
                    theme={theme}
                />
            )}

            <View className="mb-4">
                <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase tracking-widest font-bold mb-1">
                    Status do Treino
                </Text>
            </View>



            {/* Main Status Card */}
            <View
                style={{
                    backgroundColor: theme.colors.card,
                    borderColor: theme.colors.cardBorder,
                    shadowColor: theme.colors.shadow,
                    shadowOffset: { width: 0, height: 4 },
                    shadowOpacity: 0.1,
                    shadowRadius: 10,
                    elevation: 5
                }}
                className="rounded-3xl border p-5 mb-5"
            >
                <View className="flex-row items-center justify-between mb-4">
                    <View className="flex-row items-center">
                        <View style={{ backgroundColor: isCompleted ? '#10B98120' : theme.colors.backgroundTertiary }} className="w-10 h-10 rounded-full items-center justify-center mr-3">
                            <Ionicons
                                name={isCompleted ? "checkmark-circle" : "barbell"}
                                size={20}
                                color={isCompleted ? "#10B981" : theme.colors.textMuted}
                            />
                        </View>
                        <View>
                            <Text style={{ color: theme.colors.text }} className="font-bold text-base">
                                {isCompleted ? 'Treino do dia' : 'Treino de hoje'}
                            </Text>
                            <Text style={{ color: theme.colors.textMuted }} className="text-xs">
                                {type}
                            </Text>
                        </View>
                    </View>

                    <View style={{
                        backgroundColor: isCompleted ? '#10B98120' : '#EF444420',
                        paddingHorizontal: 10,
                        paddingVertical: 4,
                        borderRadius: 8
                    }}>
                        <Text style={{
                            color: isCompleted ? '#10B981' : '#EF4444',
                            fontWeight: 'bold',
                            fontSize: 12
                        }}>
                            {status}
                        </Text>
                    </View>
                </View>

                {isCompleted && (
                    <View className="flex-row border-t border-dashed pt-4" style={{ borderColor: theme.colors.border }}>
                        <View className="flex-1 items-center border-r" style={{ borderColor: theme.colors.border }}>
                            <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Duração</Text>
                            <Text style={{ color: theme.colors.text }} className="font-bold">{duration}</Text>
                        </View>
                        <View className="flex-1 items-center">
                            <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Calorias</Text>
                            <Text style={{ color: theme.colors.text }} className="font-bold">{calories}</Text>
                        </View>
                    </View>
                )}
            </View>

            {/* Exercise Details List */}
            {isCompleted && exercises.length > 0 && (
                <View>
                    <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase tracking-widest font-bold mb-3">
                        Exercícios Realizados
                    </Text>
                    <View
                        style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.cardBorder }}
                        className="rounded-2xl border px-4 py-2"
                    >
                        {exercises.map((ex, idx) => {
                            const comparison = getComparison(ex.id, ex.sets);
                            const bestSet = ex.sets.reduce((prev, current) => (Number(prev.kg || 0) > Number(current.kg || 0)) ? prev : current);

                            return (
                                <View
                                    key={idx}
                                    className={`flex-row items-center py-3 ${idx < exercises.length - 1 ? 'border-b' : ''}`}
                                    style={{ borderColor: theme.colors.border }}
                                >
                                    <Ionicons name="checkmark-circle" size={16} color="#10B981" style={{ marginRight: 10 }} />

                                    <View className="flex-1">
                                        <Text style={{ color: theme.colors.text }} className="font-medium text-sm">
                                            {ex.name}
                                        </Text>
                                        <Text style={{ color: theme.colors.textMuted }} className="text-xs">
                                            {ex.sets.length}x{bestSet.reps} • {bestSet.kg}kg
                                        </Text>
                                    </View>

                                    {comparison && comparison.type === 'better' && (
                                        <View className="bg-green-500/10 px-2 py-1 rounded-md">
                                            <Text className="text-green-500 text-xs font-bold">⬆️ {comparison.text}</Text>
                                        </View>
                                    )}
                                    {comparison && comparison.type === 'worse' && (
                                        <View className="bg-red-500/10 px-2 py-1 rounded-md">
                                            <Text className="text-red-500 text-xs font-bold">⬇️ {comparison.text}</Text>
                                        </View>
                                    )}
                                </View>
                            );
                        })}
                    </View>
                </View>
            )}
        </View>
    );
}
