import React, { useEffect } from 'react';
import { StyleSheet, View, Image, Dimensions, useColorScheme } from 'react-native';
import Animated, {
    useSharedValue,
    useAnimatedStyle,
    withTiming,
    Easing,
    runOnJS
} from 'react-native-reanimated';

import { StatusBar } from 'expo-status-bar';

const { width, height } = Dimensions.get('window');

interface Props {
    onFinish: () => void;
}

export const AnimatedSplashScreen: React.FC<Props> = ({ onFinish }) => {
    const colorScheme = useColorScheme();
    const isDark = colorScheme === 'dark';

    const opacity = useSharedValue(0);
    const scale = useSharedValue(1.1);

    useEffect(() => {
        // Smooth fade and scale animation
        opacity.value = withTiming(1, { duration: 1000, easing: Easing.out(Easing.quad) });
        scale.value = withTiming(1, { duration: 1500, easing: Easing.out(Easing.quad) });

        // End splash after 2.5s
        const timer = setTimeout(() => {
            opacity.value = withTiming(0, { duration: 500 }, (finished) => {
                if (finished) {
                    runOnJS(onFinish)();
                }
            });
        }, 2500);

        return () => clearTimeout(timer);
    }, []);

    const bgStyle = useAnimatedStyle(() => ({
        opacity: opacity.value,
        transform: [{ scale: scale.value }]
    }));

    return (
        <View style={[styles.container, { backgroundColor: isDark ? '#000000' : '#FFFFFF' }]}>
            <StatusBar style={isDark ? 'light' : 'dark'} />
            <Animated.Image
                source={isDark
                    ? require('../assets/images/splash.png')
                    : require('../assets/images/splash-light.png')
                }
                style={[styles.background, bgStyle]}
                resizeMode="contain"
            />
        </View>
    );
};

const styles = StyleSheet.create({
    container: {
        ...StyleSheet.absoluteFillObject,
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 9999,
    },
    background: {
        width: width,
        height: height,
    }
});
