import React, { useState, useMemo, useEffect, useCallback, memo } from 'react';
import { View, Text, FlatList, TouchableOpacity, Image, TextInput } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { useFavorites } from '../context/FavoritesContext';
import { useTheme } from '../context/ThemeContext';
import { useFonts } from 'expo-font';

// Import exercise data
const exercisesData = require('../assets/exercises.json');

// Category definitions with Ionicons
const CATEGORIES = [
    { id: 'all', name: 'Todos', icon: 'grid-outline' },
    { id: 'favorites', name: 'Favoritos', icon: 'heart' },
    { id: 'cardio', name: 'Cardio', icon: 'fitness' },
    { id: 'Peito', name: 'Peito', icon: 'body' },
    { id: 'Costas', name: 'Costas', icon: 'body-outline' },
    { id: 'Bíceps', name: 'Bíceps', icon: 'barbell' },
    { id: 'Tríceps', name: 'Tríceps', icon: 'barbell-outline' },
    { id: 'Quadríceps', name: 'Quadríceps', icon: 'footsteps' },
    { id: 'Isquiotibiais', name: 'Posteriores', icon: 'walk' },
    { id: 'Ombros', name: 'Ombros', icon: 'hand-left' },
    { id: 'Quadris', name: 'Quadris', icon: 'accessibility' },
    { id: 'Cintura', name: 'Cintura', icon: 'resize' },
    { id: 'Braços', name: 'Braços', icon: 'hand-right' },
    { id: 'Panturrilhas', name: 'Panturrilhas', icon: 'footsteps-outline' },
    { id: 'Antebraços', name: 'Antebraços', icon: 'hand-left-outline' },
    { id: 'Pescoço', name: 'Pescoço', icon: 'person' },
];

const BODY_PART_MAPPING: Record<string, string[]> = {
    all: [],
    favorites: [],
    cardio: ['cardio'],
    Peito: ['Peito'],
    Costas: ['Costas'], // 'Costas Superiores', 'Costas Inferiores' are implicitly handled if we search includes? No, database changed body_parts list.
    Bíceps: ['Bíceps'],
    Tríceps: ['Tríceps'],
    Quadríceps: ['Quadríceps'],
    Isquiotibiais: ['Isquiotibiais', 'Posteriores'],
    Ombros: ['Ombros'],
    Quadris: ['Quadris', 'Glúteos'],
    Cintura: ['Cintura', 'Abdômen', 'Abdominais'],
    Braços: ['Braços'],
    Panturrilhas: ['Panturrilhas'],
    Antebraços: ['Antebraços'],
    Pescoço: ['Pescoço'],
};

const BODY_PART_TRANSLATION: Record<string, string> = {
    'chest': 'Peito',
    'back': 'Costas',
    'shoulders': 'Ombros',
    'biceps': 'Bíceps',
    'triceps': 'Tríceps',
    'quadriceps': 'Quadríceps',
    'hamstrings': 'Isquiotibiais',
    'glutes': 'Glúteos',
    'calves': 'Panturrilhas',
    'abs': 'Abdômen',
    'abdominals': 'Abdominais',
    'lats': 'Dorsais',
};

const GridItem = memo(({ item, isSelected, toggleFavorite, isItemFavorite, onSelect, onInfo }: any) => (
    <TouchableOpacity
        onPress={onSelect}
        activeOpacity={0.8}
        style={{
            flex: 1,
            backgroundColor: isSelected ? '#F0F9FF' : '#FFFFFF',
            borderColor: isSelected ? '#4F8FF7' : '#E2E8F0',
            borderWidth: 1.5,
            borderRadius: 24,
            marginBottom: 16,
            marginHorizontal: 4,
            overflow: 'hidden',
            shadowColor: '#000',
            shadowOffset: { width: 0, height: 4 },
            shadowOpacity: isSelected ? 0.2 : 0.05,
            shadowRadius: 8,
            elevation: 2,
            height: 256,
        }}
    >
        <View style={{ height: 160, position: 'relative', alignItems: 'center', justifyContent: 'center' }}>
            <TouchableOpacity
                onPress={(e) => {
                    e.stopPropagation();
                    onInfo();
                }}
                activeOpacity={0.7}
                style={{ width: '100%', height: '100%', alignItems: 'center', justifyContent: 'center' }}
            >
                {item.image_url ? (
                    <Image source={{ uri: item.image_url }} style={{ width: '100%', height: '100%' }} resizeMode="contain" />
                ) : (
                    <Ionicons name="barbell" size={32} color="#CBD5E1" />
                )}
            </TouchableOpacity>
            <TouchableOpacity
                onPress={(e) => {
                    e.stopPropagation();
                    toggleFavorite(item.id?.toString());
                }}
                style={{ position: 'absolute', top: 12, left: 12, padding: 4 }}
            >
                <Ionicons name={isItemFavorite ? "bookmark" : "bookmark-outline"} size={22} color={isItemFavorite ? "#EF4444" : "#CBD5E1"} />
            </TouchableOpacity>
            <TouchableOpacity
                onPress={onInfo}
                style={{ position: 'absolute', top: 12, right: 12, padding: 4 }}
            >
                <Ionicons name="information-circle-outline" size={22} color="#CBD5E1" />
            </TouchableOpacity>
        </View>
        <View style={{ padding: 12, flex: 1, justifyContent: 'space-between' }}>
            <View>
                <Text style={{ color: isSelected ? '#4F8FF7' : '#0F172A', fontWeight: '700', fontSize: 14 }} numberOfLines={2}>
                    {item.name}
                </Text>
                <Text style={{ color: '#64748B', fontSize: 12, marginTop: 2 }}>
                    {item.body_parts?.[0] ? (BODY_PART_TRANSLATION[item.body_parts[0].toLowerCase()] || item.body_parts[0]) : 'Geral'}
                </Text>
            </View>
        </View>
    </TouchableOpacity >
));

const ExerciseCardItem = memo(({ item, isSelected, isItemFavorite, onSelect, onInfo, allowMultiSelect }: any) => (
    <TouchableOpacity
        onPress={onSelect}
        activeOpacity={0.8}
        style={{
            backgroundColor: isSelected ? '#F0F9FF' : '#FFFFFF',
            borderColor: isSelected ? '#4F8FF7' : '#E2E8F0',
            borderWidth: 1.5,
            borderRadius: 20,
            marginBottom: 12,
            overflow: 'hidden',
            shadowColor: '#000',
            shadowOffset: { width: 0, height: 2 },
            shadowOpacity: 0.05,
            shadowRadius: 4,
            elevation: 1,
        }}
    >
        <View style={{ flexDirection: 'row' }}>
            <TouchableOpacity
                onPress={(e) => {
                    e.stopPropagation();
                    onInfo();
                }}
                activeOpacity={0.7}
                style={{ width: 100, height: 100, position: 'relative', alignItems: 'center', justifyContent: 'center' }}
            >
                <Image source={{ uri: item.image_url }} style={{ width: '100%', height: '100%' }} resizeMode="contain" />
                <TouchableOpacity
                    onPress={onInfo}
                    style={{ position: 'absolute', top: 4, right: 4, backgroundColor: 'rgba(0,0,0,0.5)', borderRadius: 100, padding: 2 }}
                >
                    <Ionicons name="information" size={12} color="white" />
                </TouchableOpacity>
            </TouchableOpacity>
            <View style={{ flex: 1, padding: 12, justifyContent: 'center' }}>
                <Text style={{ color: isSelected ? '#4F8FF7' : '#0F172A', fontWeight: '700', fontSize: 16 }} numberOfLines={2}>
                    {item.name}
                </Text>
                <View style={{ flexDirection: 'row', flexWrap: 'wrap', marginTop: 4 }}>
                    {item.body_parts?.slice(0, 2).map((part: string, idx: number) => (
                        <View key={idx} style={{ backgroundColor: '#F1F5F9', paddingHorizontal: 8, paddingVertical: 2, borderRadius: 100, marginRight: 4, marginBottom: 4 }}>
                            <Text style={{ color: '#64748B', fontSize: 10 }}>
                                {BODY_PART_TRANSLATION[part.toLowerCase()] || part}
                            </Text>
                        </View>
                    ))}
                </View>
            </View>
            <View style={{ justifyContent: 'center', paddingRight: 16 }}>
                {allowMultiSelect && (
                    <View style={{
                        width: 24,
                        height: 24,
                        borderRadius: 100,
                        backgroundColor: isSelected ? '#4F8FF7' : 'transparent',
                        borderColor: isSelected ? '#4F8FF7' : '#CBD5E1',
                        borderWidth: 1,
                        alignItems: 'center',
                        justifyContent: 'center'
                    }}>
                        {isSelected && <Ionicons name="checkmark" size={16} color="white" />}
                    </View>
                )}
            </View>
        </View>
    </TouchableOpacity >
));

export function LibraryView({
    onExerciseSelect,
    initialCategory = 'all',
    hideHeader = false,
    externalSearchQuery = '',
    onCategoryChange,
    allowMultiSelect = false,
    onBatchSelect
}: {
    onExerciseSelect?: (exercise: any) => void,
    initialCategory?: string,
    hideHeader?: boolean,
    externalSearchQuery?: string,
    onCategoryChange?: (categoryId: string) => void,
    allowMultiSelect?: boolean,
    onBatchSelect?: (exercises: any[]) => void
}) {
    const router = useRouter();
    const [selectedCategory, setSelectedCategory] = useState(initialCategory);
    const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

    // Sync prop changes (for deep linking)
    useEffect(() => {
        if (initialCategory) {
            setSelectedCategory(initialCategory);
        }
    }, [initialCategory]);

    const [searchQuery, setSearchQuery] = useState('');
    const { favorites, isFavorite, toggleFavorite } = useFavorites();
    const { theme } = useTheme();
    const insets = useSafeAreaInsets();

    const filteredExercises = useMemo(() => {
        let filtered = exercisesData;

        if (selectedCategory === 'favorites') {
            filtered = filtered.filter((ex: any) =>
                favorites.includes(ex.id?.toString())
            );
        } else if (selectedCategory !== 'all') {
            const targetBodyParts = BODY_PART_MAPPING[selectedCategory] || [];
            filtered = filtered.filter((ex: any) =>
                ex.body_parts?.some((part: string) =>
                    targetBodyParts.some(target => part.toLowerCase().includes(target.toLowerCase()))
                )
            );
        }

        const effectiveSearch = externalSearchQuery || searchQuery;
        if (effectiveSearch.trim()) {
            const query = effectiveSearch.toLowerCase();
            filtered = filtered.filter((ex: any) =>
                ex.name?.toLowerCase().includes(query)
            );
        }

        return filtered;
    }, [selectedCategory, searchQuery, externalSearchQuery, favorites]);

    const toggleSelection = (id: string) => {
        const newSet = new Set(selectedIds);
        if (newSet.has(id)) {
            newSet.delete(id);
        } else {
            newSet.add(id);
        }
        setSelectedIds(newSet);
    };

    const handleBatchAdd = () => {
        const selectedIdArray = Array.from(selectedIds);
        const selectedExercises = exercisesData.filter((ex: any) => selectedIdArray.includes(ex.id?.toString()));

        if (onBatchSelect) {
            onBatchSelect(selectedExercises);
            setSelectedIds(new Set());
        } else if (onExerciseSelect) {
            selectedExercises.forEach((ex: any) => {
                onExerciseSelect(ex);
            });
            setSelectedIds(new Set());
        }
    };

    const handleItemSelect = useCallback((item: any) => {
        if (onExerciseSelect && allowMultiSelect) {
            toggleSelection(item.id?.toString());
        } else if (onExerciseSelect) {
            onExerciseSelect(item);
        } else {
            router.push(`/exercise/${item.id}?source=library`);
        }
    }, [onExerciseSelect, allowMultiSelect, router]);

    const handleInfo = useCallback((id: string) => {
        router.push(`/exercise/${id}?source=library`);
    }, [router]);

    const renderItem = useCallback(({ item }: { item: any }) => {
        const isItemFavorite = isFavorite(item.id?.toString());
        const isSelected = selectedIds.has(item.id?.toString());

        if (viewMode === 'grid') {
            return (
                <GridItem
                    item={item}
                    isSelected={isSelected}
                    isItemFavorite={isItemFavorite}
                    toggleFavorite={toggleFavorite}
                    onSelect={() => handleItemSelect(item)}
                    onInfo={() => handleInfo(item.id)}
                />
            );
        }
        return (
            <ExerciseCardItem
                item={item}
                isSelected={isSelected}
                isItemFavorite={isItemFavorite}
                onSelect={() => handleItemSelect(item)}
                onInfo={() => handleInfo(item.id)}
                allowMultiSelect={allowMultiSelect}
            />
        );
    }, [viewMode, selectedIds, isFavorite, toggleFavorite, handleItemSelect, handleInfo, allowMultiSelect]);

    const renderCategoryItem = ({ item }: { item: any }) => {
        const isSelected = selectedCategory === item.id;
        return (
            <TouchableOpacity
                onPress={() => {
                    setSelectedCategory(item.id);
                    if (onCategoryChange) onCategoryChange(item.id);
                }}
                activeOpacity={0.7}
                style={{
                    backgroundColor: isSelected ? theme.colors.primary : (theme.mode === 'light' ? '#F1F5F9' : theme.colors.card),
                    borderColor: isSelected ? theme.colors.primary : (theme.mode === 'light' ? '#E2E8F0' : theme.colors.cardBorder),
                    borderWidth: 1.5,
                    shadowColor: isSelected ? theme.colors.primary : 'transparent',
                    shadowOffset: { width: 0, height: 2 },
                    shadowOpacity: isSelected ? 0.3 : 0,
                    shadowRadius: 4,
                }}
                className={`mr-2 flex-row items-center px-5 h-11 rounded-full transition-smooth`}
            >
                <Ionicons
                    name={item.icon as any}
                    size={18}
                    color={isSelected ? '#FFFFFF' : theme.colors.textMuted}
                />
                <Text style={{
                    color: isSelected ? '#FFFFFF' : theme.colors.text,
                    fontWeight: isSelected ? '700' : '500'
                }} className="ml-2 text-sm">
                    {item.name}
                </Text>
            </TouchableOpacity>
        );
    };

    return (
        <View style={{ flex: 1, backgroundColor: theme.colors.background }} className="relative">
            {!hideHeader && (
                <View className="px-4 mb-2">
                    <View style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.cardBorder }} className="flex-row items-center rounded-2xl px-4 h-12 mb-4 border">
                        <Ionicons name="search" size={20} color={theme.colors.textMuted} />
                        <TextInput
                            value={searchQuery}
                            onChangeText={setSearchQuery}
                            placeholder="Buscar exercícios..."
                            placeholderTextColor={theme.colors.textMuted}
                            style={{ color: theme.colors.text }}
                            className="flex-1 ml-2 text-base font-medium"
                        />
                        {searchQuery.length > 0 && (
                            <TouchableOpacity onPress={() => setSearchQuery('')}>
                                <Ionicons name="close-circle" size={20} color={theme.colors.textMuted} />
                            </TouchableOpacity>
                        )}
                    </View>

                    <View className="flex-row items-center mb-4">
                        <FlatList
                            data={CATEGORIES}
                            renderItem={renderCategoryItem}
                            keyExtractor={(item) => item.id}
                            horizontal
                            showsHorizontalScrollIndicator={false}
                            contentContainerStyle={{ paddingRight: 16 }}
                            className="flex-1"
                        />

                        <View className="flex-row items-center ml-2 border-l pl-3 gap-2" style={{ borderLeftColor: theme.colors.border }}>
                            <TouchableOpacity
                                onPress={() => setViewMode(prev => prev === 'list' ? 'grid' : 'list')}
                                style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.cardBorder }}
                                className="p-2.5 rounded-xl border shadow-sm"
                            >
                                <Ionicons name={viewMode === 'list' ? "grid-outline" : "list-outline"} size={20} color={theme.colors.textMuted} />
                            </TouchableOpacity>
                        </View>
                    </View>
                </View>
            )}

            <FlatList
                key={viewMode} // Force re-render solely for structure swap (1 vs 2 cols)
                data={filteredExercises}
                renderItem={renderItem}
                keyExtractor={(item) => item.id}
                contentContainerStyle={{
                    padding: 16,
                    paddingBottom: insets.bottom + 40
                }}
                columnWrapperStyle={viewMode === 'grid' ? { justifyContent: 'space-between' } : undefined}
                numColumns={viewMode === 'grid' ? 2 : 1}
                showsVerticalScrollIndicator={false}
                initialNumToRender={10}
                maxToRenderPerBatch={10}
                windowSize={5}
                removeClippedSubviews={true}
                ListEmptyComponent={
                    <View className="items-center justify-center py-20">
                        <Ionicons
                            name={selectedCategory === 'favorites' ? 'heart-outline' : 'clipboard-outline'}
                            size={48}
                            color="#64748B"
                        />
                        <Text className="text-text-muted mt-3 text-center">
                            {selectedCategory === 'favorites'
                                ? 'Nenhum exercício favoritado ainda.\nToque no ❤️ para adicionar favoritos!'
                                : 'Nenhum exercício encontrado'
                            }
                        </Text>
                    </View>
                }
            />

            {/* Batch Add Floating Button */}
            {selectedIds.size > 0 && onExerciseSelect && allowMultiSelect && (
                <View className="absolute bottom-10 left-6 right-6">
                    <TouchableOpacity
                        onPress={handleBatchAdd}
                        className="bg-primary py-4 rounded-xl flex-row justify-center items-center shadow-lg"
                        style={{ shadowColor: '#4F8FF7', shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.3, shadowRadius: 8 }}
                    >
                        <Text className="text-black font-bold text-lg mr-2">
                            Adicionar ({selectedIds.size})
                        </Text>
                        <Ionicons name="add-circle" size={24} color="black" />
                    </TouchableOpacity>
                </View>
            )}
        </View>
    );
}
