import React, { useState, useMemo } from 'react';
import { View, Text, ScrollView, TouchableOpacity, Modal } from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { StatusBar } from 'expo-status-bar';
import { useTheme } from '../context/ThemeContext';
import { useMuscleTracker, MuscleId, MuscleData } from '../context/MuscleTrackerContext';


export default function MuscleTrackingScreen() {
    const { theme } = useTheme();
    const router = useRouter();
    const { muscleStats, loading } = useMuscleTracker();
    const [selectedMuscle, setSelectedMuscle] = useState<MuscleData | null>(null);
    const [showModal, setShowModal] = useState(false);

    const handleMusclePress = (id: MuscleId) => {
        const data = muscleStats[id];
        if (data) {
            setSelectedMuscle(data);
            setShowModal(true);
        }
    };

    // Calculate "Focus of the Day"
    const suggestions = useMemo(() => {
        return Object.values(muscleStats)
            .filter(m => m.status === 'undertrained')
            .sort((a, b) => a.score - b.score) // Lowest score first
            .slice(0, 2);
    }, [muscleStats]);

    if (loading) {
        return <View className="flex-1 justify-center items-center"><Text>Carregando...</Text></View>;
    }

    return (
        <View style={{ flex: 1, backgroundColor: theme.colors.background }}>
            <StatusBar style={theme.mode === 'light' ? 'dark' : 'light'} />

            {/* Header */}
            <View style={{ backgroundColor: theme.colors.background }} className="flex-row items-center justify-between px-6 pt-14 pb-4">
                <View className="flex-row items-center">
                    <TouchableOpacity onPress={() => router.back()} className="mr-6">
                        <Ionicons name="arrow-back" size={26} color={theme.colors.text} />
                    </TouchableOpacity>
                    <Text style={{ color: theme.colors.text }} className="text-xl font-bold">Acompanhamento</Text>
                </View>
                <TouchableOpacity onPress={() => { }}>
                    <Ionicons name="information-circle-outline" size={24} color={theme.colors.text} />
                </TouchableOpacity>
            </View>

            <ScrollView className="flex-1" contentContainerStyle={{ paddingBottom: 100 }}>

                {/* 🎯 Focus of the Day */}
                <View className="px-6 mb-8">
                    <Text style={{ color: theme.colors.text }} className="text-lg font-bold mb-3">🎯 Foco Recomendado</Text>
                    {suggestions.length > 0 ? (
                        suggestions.map(muscle => (
                            <TouchableOpacity
                                key={muscle.id}
                                onPress={() => handleMusclePress(muscle.id as MuscleId)}
                                style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.border }}
                                className="p-4 rounded-2xl border mb-3 flex-row justify-between items-center shadow-sm"
                            >
                                <View>
                                    <View className="flex-row items-center mb-1">
                                        <Text style={{ color: theme.colors.text }} className="font-bold text-base mr-2">{muscle.name}</Text>
                                        <View className="bg-yellow-500/20 px-2 py-0.5 rounded text-xs bg-opacity-20">
                                            <Text className="text-yellow-600 text-[10px] font-bold">SUBTREINADO</Text>
                                        </View>
                                    </View>
                                    <Text style={{ color: theme.colors.textSecondary }} className="text-xs">
                                        Último treino: {muscle.lastTrained ? new Date(muscle.lastTrained).toLocaleDateString('pt-BR') : 'Nunca'}
                                    </Text>
                                </View>
                                <Ionicons name="chevron-forward" size={20} color={theme.colors.textMuted} />
                            </TouchableOpacity>
                        ))
                    ) : (
                        <View style={{ backgroundColor: theme.colors.card }} className="p-4 rounded-2xl">
                            <Text style={{ color: theme.colors.text }}>Tudo equilibrado! Bom trabalho.</Text>
                        </View>
                    )}
                </View>

                {/* 📊 Detailed Stats List */}
                <View className="px-6">
                    <Text style={{ color: theme.colors.text }} className="text-lg font-bold mb-4">Status Geral</Text>
                    {Object.values(muscleStats).map(muscle => (
                        <TouchableOpacity
                            key={muscle.id}
                            onPress={() => handleMusclePress(muscle.id as MuscleId)}
                            style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.border }}
                            className="p-4 rounded-xl border mb-2 flex-row justify-between items-center"
                        >
                            <View className="flex-row items-center">
                                <View className={`w-2 h-10 rounded-full mr-4 ${muscle.status === 'recovered' ? 'bg-green-500' :
                                    muscle.status === 'undertrained' ? 'bg-yellow-500' :
                                        muscle.status === 'overreaching' ? 'bg-red-500' : 'bg-blue-500'
                                    }`} />
                                <View>
                                    <Text style={{ color: theme.colors.text }} className="font-bold">{muscle.name}</Text>
                                    <Text style={{ color: theme.colors.textMuted }} className="text-xs">{muscle.setsThisWeek} séries / semana</Text>
                                </View>
                            </View>
                            <View className="items-end">
                                <Text style={{ color: theme.colors.text }} className="font-bold text-lg">{muscle.score}</Text>
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] uppercase">Score</Text>
                            </View>
                        </TouchableOpacity>
                    ))}
                </View>

            </ScrollView>

            {/* Muscle Detail Modal */}
            <Modal
                visible={showModal}
                transparent={true}
                animationType="slide"
                onRequestClose={() => setShowModal(false)}
            >
                <View className="flex-1 justify-end">
                    <TouchableOpacity
                        style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.5)' }}
                        activeOpacity={1}
                        onPress={() => setShowModal(false)}
                    />
                    <View style={{ backgroundColor: theme.colors.card, borderTopLeftRadius: 30, borderTopRightRadius: 30 }} className="p-6 h-[60%]">
                        {selectedMuscle && (
                            <>
                                <View className="items-center mb-6">
                                    <View className="w-12 h-1 bg-gray-300 dark:bg-gray-600 rounded-full mb-6" />
                                    <Text style={{ color: theme.colors.text }} className="text-3xl font-bold mb-1">{selectedMuscle.name}</Text>
                                    <View className={`px-3 py-1 rounded-full ${selectedMuscle.status === 'recovered' ? 'bg-green-500/20' :
                                        selectedMuscle.status === 'undertrained' ? 'bg-yellow-500/20' :
                                            selectedMuscle.status === 'overreaching' ? 'bg-red-500/20' : 'bg-blue-500/20'
                                        }`}>
                                        <Text className={`font-bold ${selectedMuscle.status === 'recovered' ? 'text-green-500' :
                                            selectedMuscle.status === 'undertrained' ? 'text-yellow-500' :
                                                selectedMuscle.status === 'overreaching' ? 'text-red-500' : 'text-blue-500'
                                            }`}>
                                            {selectedMuscle.status === 'recovered' ? 'Volume Ideal ✅' :
                                                selectedMuscle.status === 'undertrained' ? 'Subtreinado ⚠️' :
                                                    selectedMuscle.status === 'overreaching' ? 'Sobrecarga 🚨' : 'Em Recuperação 💤'}
                                        </Text>
                                    </View>
                                </View>

                                {/* Coach Recommendation */}
                                <View style={{ backgroundColor: theme.colors.background }} className="p-4 rounded-xl mb-6 border border-l-4 border-l-primary border-zinc-100 dark:border-zinc-800">
                                    <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase font-bold mb-1">Coach diz:</Text>
                                    <Text style={{ color: theme.colors.text }} className="text-base font-medium">"{selectedMuscle.recommendation}"</Text>
                                </View>

                                {/* Metrics Grid */}
                                <View className="flex-row flex-wrap justify-between gap-y-4 mb-6">
                                    <View className="w-[48%] bg-zinc-50 dark:bg-zinc-900/50 p-4 rounded-xl">
                                        <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Volume Semanal</Text>
                                        <Text style={{ color: theme.colors.text }} className="text-xl font-bold">{selectedMuscle.setsThisWeek} <Text className="text-sm font-normal text-gray-500">/ {selectedMuscle.weeklyTarget}</Text></Text>
                                    </View>
                                    <View className="w-[48%] bg-zinc-50 dark:bg-zinc-900/50 p-4 rounded-xl">
                                        <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Recuperação</Text>
                                        <Text style={{ color: theme.colors.text }} className="text-xl font-bold">{selectedMuscle.recoveryPercentage}%</Text>
                                    </View>
                                    <View className="w-[48%] bg-zinc-50 dark:bg-zinc-900/50 p-4 rounded-xl">
                                        <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Último Treino</Text>
                                        <Text style={{ color: theme.colors.text }} className="text-lg font-bold">
                                            {selectedMuscle.lastTrained
                                                ? new Date(selectedMuscle.lastTrained).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })
                                                : '--/--'}
                                        </Text>
                                    </View>
                                    <View className="w-[48%] bg-zinc-50 dark:bg-zinc-900/50 p-4 rounded-xl">
                                        <Text style={{ color: theme.colors.textMuted }} className="text-xs mb-1">Score</Text>
                                        <Text style={{ color: theme.colors.text }} className="text-xl font-bold">{selectedMuscle.score}/100</Text>
                                    </View>
                                </View>

                            </>
                        )}
                        <TouchableOpacity
                            onPress={() => setShowModal(false)}
                            style={{ backgroundColor: theme.colors.primary }}
                            className="w-full py-4 rounded-xl items-center mt-auto shadow-lg"
                        >
                            <Text className="text-white font-bold text-lg">Entendido</Text>
                        </TouchableOpacity>
                    </View>
                </View>
            </Modal>
        </View>
    );
}
